// A desktop of 1996 around the scene it wraps: the WarpCenter along the top, the
// LaunchPad on the desktop, and the scene in a window with its title centered
// and the system menu at its left. The WarpCenter's first button opens the
// Desktop menu (the frame's scenes), the second the Window List; its tray has
// the frame's own apps, and the signal, the battery, the date and the clock at
// its right end open the frame's page, System Setup. Built-in scenes are drawn
// in the window too.
//
// On a frame that runs its scenes side by side (app.frame.scenes is there), it is
// a desktop: every scene opened is a window, and they all run at once (on an ESP32
// as many as app.frame.windows says, and one more opened closes the one that had
// the focus longest ago), and chosen in another desktop's place (the frame page's
// Layout), it opens what that one had open. A window opens at its scene's own
// size (its settings.windowSize), else at 800x480, a 7.5-inch frame's, filling the
// desktop where that does not fit, where it covers the least of the windows open,
// the icons and the LaunchPad (all of it on bare desktop where there is room), and
// where it was when its scene opens again. The scene with the focus is the
// frame's own (the <yield />), the others are <Scene>s. Drag a title bar to move a
// window and an edge to size it, double click it (or its maximize button) to fill
// the desktop, let it go at the top edge to fill it or at a side to take that
// half. The icon at a title bar's left opens the window's system menu (Restore,
// Hide, Maximize, Settings, Window list, Close), the gear its scene's settings
// ("Clock - Settings", a window a scene, several open at once), the hide button
// takes it off the desktop and into the Window List, which brings it back, tiles
// the windows or cascades them. The LaunchPad's buttons open the Window List, the
// scenes, the frame's own apps and System Setup, and the arrow over Scenes its
// drawer of scenes. A right click or a long press on the desktop opens its
// pop-up menu; a rectangle drawn on it picks the icons it touches, and a drag
// puts what is picked elsewhere, where it stays. The keys are OS/2's: Ctrl+Esc the Window List, Alt+Tab the next
// window, Alt+F4 closes, Alt+F9 hides, Alt+F10 maximizes, Alt+F5 restores, and
// F11 gives the panel to the window in front (Escape takes it back). The frame's
// own scenes open in windows of their own over the scene, stay open while
// another window has the focus, and close when they go back by themselves
// (Save, Cancel, a scene picked).
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// The frame's own scenes (the contract's `scenes.settings` and `scenes.switcher`),
// and the command that opens each, which also sends it back.
const SETTINGS = 'system/sceneSettings'
// On a desktop every scene's settings are a scene of their own, this and the
// scene's id (the contract's `scenes.settingsWindow`); the plain id is the frame's
// page, System Setup.
const SETTINGS_OF = 'system/sceneSettings#'
const settingsOf = (id) => SETTINGS_OF + id
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const SWITCHER = 'system/sceneSwitcher'
const commandOf = (id) => (id === SWITCHER ? 'sceneSwitcher' : 'sceneSettings')
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// A built-in scene the focus left is still open beside the scene showing, its
// page and edits as they were, unless it went back by itself: the host says
// which (app.frame.keptOpen). Before 2026.11.14 a layout guessed: open if it
// moved the focus itself (`asked`) or to another built-in scene.
const keptOpen = (app, id, current) =>
  Array.isArray(app.frame.keptOpen) ? app.frame.keptOpen.includes(id) : isSystem(current) || app.state.asked === current
// The frame's own apps that are scenes like any other, which the frame may have
// (docs/scene-store.md, docs/terminal.md): the scene store, Files and the
// terminal, by their sample's id, or by their name where a control plane gave
// them another id (Files by its old name too, "Asset browser"). A desktop has
// entries of its own for them, and leaves them out of its scene lists.
const appIs = (id, ...names) => (scene) =>
  !!scene && (scene.id === id || names.includes(String(scene.name || '').trim().toLowerCase()))
const isStore = appIs('scene-store', 'scene store')
const isFiles = appIs('asset-browser', 'files', 'asset browser')
const isTerminal = appIs('terminal-app', 'terminal')
const isFrameApp = (scene) => isStore(scene) || isFiles(scene) || isTerminal(scene)
// A list of scenes in groups by their category (`category` on each entry of
// app.frame.scenes: the scene's settings.category, its name, "Photos"): one
// group under each name, System first (the frame's own apps), the others by
// name whatever the case, and the scenes with none (or "Other") last, as Other.
// Where no scene has one, one group with no title: the list as it always was.
// Every desktop with a list of scenes has this same function.
function grouped(scenes) {
  const nameOf = (scene) => {
    const name = typeof scene.category === 'string' ? scene.category.trim() : ''
    return name.toLowerCase() === 'other' ? '' : name
  }
  const names = []
  for (const scene of scenes) {
    const name = nameOf(scene)
    if (name && !names.includes(name)) names.push(name)
  }
  if (!names.length) return [{ title: null, scenes }]
  names.sort((a, b) => {
    const x = a.toLowerCase()
    const y = b.toLowerCase()
    if ((x === 'system') !== (y === 'system')) return x === 'system' ? -1 : 1
    return x < y ? -1 : x > y ? 1 : a < b ? -1 : a > b ? 1 : 0
  })
  const groups = names.map((title) => ({ title, scenes: scenes.filter((scene) => nameOf(scene) === title) }))
  const rest = scenes.filter((scene) => !nameOf(scene))
  if (rest.length) groups.push({ title: 'Other', scenes: rest })
  return groups
}
// A scene's own icon (`icon` on its entry of app.frame.scenes, docs/scene-icons.md):
// one path in a 24 box, filled in the color of the text around it, `size` wide
// and high (a length); null where the scene has none, and the desktop draws its
// own. Every desktop that draws its scenes' icons has this same function.
function ownIcon(scene, size) {
  if (!scene || typeof scene.icon !== 'string' || !scene.icon) return null
  return (
    <svg viewBox="0 0 24 24" className={`shrink-0 w-[${size}] h-[${size}]`}>
      <path d={scene.icon} fill="currentColor" />
    </svg>
  )
}
const findScene = (app, test) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(test) : undefined)
const storeOf = (app) => findScene(app, isStore)
const filesOf = (app) => findScene(app, isFiles)
const terminalOf = (app) => findScene(app, isTerminal)
const BAG = 'M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z'
const GEAR =
  'M20 9L21 3L27 3L28 9L32 11L36 7L41 12L37 16L39 20L45 21L45 27L39 28L37 32L41 36L36 41L32 37L28 39L27 45L21 45L20 39L16 37L12 41L7 36L11 32L9 28L3 27L3 21L9 20L11 16L7 12L12 7L16 11ZM17 24a7 7 0 1 0 14 0a7 7 0 1 0 -14 0Z'

// The colors: the pale grey of every window, button and menu, the desktop's
// blue, and the dark blue of the window in front's title bar and of what is
// picked.
const DESK = '#3b7090'
const TITLE = '#20406f'

// ------------------------------------------------------------ the frame's pages
//
// The frame's own pages (a scene's settings, the frame's, the scene list, the
// keyboard on the screen) in this layout's look: a theme is each
// kind of element's classes (docs/jsx-ui.md "Themes"), a string for one box or a
// list for boxes inside each other (a bevel is two or three, as a box has one
// border color). The layout keeps it in its state as `theme`, where the frame
// reads it; not on e-paper but for high contrast.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
}

function dress(app, themes, fallback) {
  const name = String(app.state.look || fallback)
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : themes[name] || null
  const key = theme ? name : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

// A push button: a dark line around a bevel, light at the top left and dark at
// the bottom right, which swap while it is pressed; sunk as a field is; and an
// etched group.
const RAISED = [
  'bg-[#cccccc] active:bg-[#b4b4b4] border-1 border-[#404040]',
  'border-t-1 border-l-1 border-white active:border-[#808080]',
  'border-b-1 border-r-1 border-[#808080] active:border-white',
]
const SUNK = ['border-t-1 border-l-1 border-[#808080]', 'border-b-1 border-r-1 border-white']
const LIT = ['bg-[#e6e6e6] border-1 border-[#404040]', 'border-t-1 border-l-1 border-[#808080]', 'border-b-1 border-r-1 border-white']
const THEMES = {
  warp: {
    page: 'bg-[#cccccc] text-black',
    bar: 'border-b-1 border-[#808080]',
    button: RAISED,
    primary: ['border-1 border-black', ...RAISED],
    selected: LIT,
    field: [...SUNK, 'bg-white text-black border-1 border-[#404040] placeholder:text-[#808080]'],
    option: `active:bg-[${TITLE}] active:text-white`,
    picked: `bg-[${TITLE}] text-white`,
    switch: [...SUNK, 'bg-white'],
    switchOn: [...SUNK, `bg-[${TITLE}]`],
    knob: RAISED.slice(0, 2),
    knobOn: RAISED.slice(0, 2),
    muted: 'text-[#4c4c4c]',
    card: ['border-t-1 border-l-1 border-[#808080]', 'border-b-1 border-r-1 border-white', 'border-t-1 border-l-1 border-white', 'border-b-1 border-r-1 border-[#808080]'],
    tile: RAISED,
    tileLit: [`border-2 border-[${TITLE}]`, ...RAISED],
    accent: `bg-[${TITLE}]`,
    keyboard: 'bg-[#cccccc] text-black border-t-1 border-white',
    key: RAISED,
    keyMod: RAISED,
    keyLit: LIT,
  },
}

// Sizes are pixels of the desktop's own, smaller in proportion under 480, which has
// no room for them. The frame's render scale makes them larger (automatic: 2 on a
// 4K screen or a 10" e-paper), which a size given as a share of the panel could not
// do, so the desktop grows no larger by itself.
let zoom = 1
let edge = 1 // the bevels' width
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`
const size = (n) => Math.round(n * zoom)
// The WarpCenter's height, its line under it included: the desktop starts there.
const barH = () => size(28)

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const date = (now) => `${DAYS[now.getDay()]} ${now.getDate()} ${MONTHS[now.getMonth()]}`

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// ------------------------------------------------------------- the pieces
//
// A box has one border color, so a bevel is boxes inside each other. Pressed,
// they swap their light and dark edges: the button goes in. `Raised` has the dark
// line around it a push button has; `Bevel` is the WarpCenter's and a title bar's.
const Raised = ({ className = '', onClick, children }) => (
  <div className={`flex bg-[#cccccc] active:bg-[#b4b4b4] border-[${edge}px] border-[#404040] ${className}`} onClick={onClick}>
    <div className={`flex flex-1 min-w-0 border-t-${edge} border-l-${edge} border-white active:border-[#808080]`}>
      <div className={`flex flex-1 min-w-0 items-center justify-center gap-[${px(4)}] px-[${px(3)}] border-b-${edge} border-r-${edge} border-[#808080] active:border-white`}>
        {children}
      </div>
    </div>
  </div>
)

const Bevel = ({ className = '', onClick, children }) => (
  <div className={`flex bg-[#cccccc] active:bg-[#b4b4b4] border-t-${edge} border-l-${edge} border-white active:border-[#808080] ${className}`} onClick={onClick}>
    <div className={`flex flex-1 min-w-0 items-center justify-center gap-[${px(4)}] px-[${px(5)}] border-b-${edge} border-r-${edge} border-[#808080] active:border-white`}>
      {children}
    </div>
  </div>
)

const Sunken = ({ className = '', onClick, children }) => (
  <div className={`flex border-t-${edge} border-l-${edge} border-[#808080] ${className}`} onClick={onClick}>
    <div className={`flex flex-1 min-w-0 items-center justify-center gap-[${px(5)}] px-[${px(6)}] border-b-${edge} border-r-${edge} border-white`}>{children}</div>
  </div>
)

// A button that stays in while what it stands for is open.
const Toggle = ({ pressed, className = '', onClick, children }) =>
  pressed ? (
    <Sunken className={`bg-[#e6e6e6] active:bg-[#b4b4b4] ${className}`} onClick={onClick}>
      {children}
    </Sunken>
  ) : (
    <Bevel className={className} onClick={onClick}>
      {children}
    </Bevel>
  )

// An etched line between the WarpCenter's groups.
const Etch = () => (
  <div className="flex shrink-0">
    <div className={`w-[${edge}px] bg-[#808080]`} />
    <div className={`w-[${edge}px] bg-white`} />
  </div>
)

// A menu's arrow down, and the LaunchPad's arrow up to a drawer.
const Caret = ({ up = false }) => (
  <svg viewBox="0 0 8 5" className={`shrink-0 w-[${px(8)}] h-[${px(5)}]`}>
    <path d={up ? 'M0 5H8L4 0Z' : 'M0 0H8L4 5Z'} fill="#000000" />
  </svg>
)

const Check = () => (
  <svg viewBox="0 0 12 12" className={`shrink-0 w-[${px(11)}] h-[${px(11)}]`}>
    <path d="M1 6.5L2.6 4.9L4.6 6.9L9.4 2.1L11 3.7L4.6 10.1Z" fill="currentColor" />
  </svg>
)

// ---------------------------------------------------------------- the icons
//
// Drawn in a 32 box, `s` pixels of the desktop's wide.
const Icon = ({ s, children }) => (
  <svg viewBox="0 0 32 32" className={`shrink-0 w-[${px(s)}] h-[${px(s)}]`}>
    {children}
  </svg>
)

// A folder of the time, its front flap leaning: the scenes.
const FolderIcon = ({ s = 32 }) => (
  <Icon s={s}>
    <path fill="#b8862e" stroke="#000000" strokeWidth="1.2" strokeLinejoin="round" d="M2.5 7.5H11.5L14 10H27.5V26.5H2.5Z" />
    <path fill="#f4d47c" stroke="#000000" strokeWidth="1.2" strokeLinejoin="round" d="M2.5 26.5L6 13.5H30.5L27 26.5Z" />
  </Icon>
)

// System Setup: a folder with a gear on it.
const SetupIcon = ({ s = 32 }) => (
  <Icon s={s}>
    <path fill="#6f8fa8" stroke="#000000" strokeWidth="1.2" strokeLinejoin="round" d="M2.5 7.5H11.5L14 10H27.5V26.5H2.5Z" />
    <path fill="#a9c3d6" stroke="#000000" strokeWidth="1.2" strokeLinejoin="round" d="M2.5 26.5L6 13.5H30.5L27 26.5Z" />
    <path fill="#404040" transform="translate(9.5 10.5) scale(0.33)" d={GEAR} />
  </Icon>
)

// The scene store: a shopping bag.
const StoreIcon = ({ s = 32 }) => (
  <svg viewBox="0 0 24 24" className={`shrink-0 w-[${px(s)}] h-[${px(s)}]`}>
    <path fill="#2f6db5" stroke="#000000" strokeWidth="1.2" strokeLinejoin="round" d={BAG} />
  </svg>
)

// Files: a drive, its light on.
const DriveIcon = ({ s = 32 }) => (
  <Icon s={s}>
    <path fill="#e2e2e2" stroke="#000000" strokeWidth="1.2" d="M2.5 11.5L6.5 7.5H25.5L29.5 11.5V23.5H2.5Z" />
    <path fill="none" stroke="#808080" strokeWidth="1.2" d="M2.5 11.5H29.5" />
    <rect x="6" y="16" width="13" height="3" fill="#808080" />
    <rect x="23" y="16" width="3.5" height="3" fill="#22b14c" />
  </Icon>
)

// The terminal: a command prompt in a window.
const PromptIcon = ({ s = 32 }) => (
  <Icon s={s}>
    <rect x="1.5" y="3.5" width="29" height="25" fill="#000000" stroke="#808080" />
    <rect x="2" y="4" width="28" height="5" fill={TITLE} />
    <path fill="none" stroke="#ffffff" strokeWidth="2" d="M6 13L10 16.5L6 20M12.5 21H19" />
  </Icon>
)

// A scene with no icon of its own: a window.
const WindowIcon = ({ s = 16 }) => (
  <svg viewBox="0 0 16 16" className={`shrink-0 w-[${px(s)}] h-[${px(s)}]`}>
    <rect x="0.5" y="1.5" width="15" height="13" fill="#ffffff" stroke="#000000" />
    <rect x="1" y="2" width="14" height="3" fill={TITLE} />
  </svg>
)

// The WarpCenter's Desktop button: a screen on a stand.
const DesktopGlyph = () => (
  <svg viewBox="0 0 16 16" className={`shrink-0 w-[${px(16)}] h-[${px(16)}]`}>
    <rect x="1.5" y="1.5" width="13" height="10" fill={DESK} stroke="#000000" />
    <path fill="none" stroke="#000000" d="M8 11.5V14M4.5 14.5H11.5" />
  </svg>
)

// The Window List: two windows, one behind the other.
const WindowsGlyph = ({ s = 16 }) => (
  <svg viewBox="0 0 16 16" className={`shrink-0 w-[${px(s)}] h-[${px(s)}]`}>
    <rect x="5.5" y="1.5" width="10" height="8" fill="#ffffff" stroke="#000000" />
    <rect x="6" y="2" width="9" height="2" fill="#808080" />
    <rect x="0.5" y="6.5" width="10" height="8" fill="#ffffff" stroke="#000000" />
    <rect x="1" y="7" width="9" height="2" fill={TITLE} />
  </svg>
)

const GearGlyph = () => (
  <svg viewBox="0 0 48 48" className={`shrink-0 w-[${px(12)}] h-[${px(12)}]`}>
    <path fill="#000000" d={GEAR} />
  </svg>
)

// The title bar's buttons: hide (a small square: the window goes to the Window
// List), maximize (the whole square) or restore, and close.
const HideGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <rect x="3" y="5" width="4" height="4" fill="#000000" />
  </svg>
)

const MaxGlyph = () => (
  <svg viewBox="0 0 10 10" className={`shrink-0 w-[${px(9)}] h-[${px(9)}]`}>
    <rect x="0.5" y="0.5" width="9" height="9" fill="none" stroke="#000000" />
    <rect x="0" y="0" width="10" height="2.4" fill="#000000" />
  </svg>
)

const RestoreGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <rect x="2.5" y="3.5" width="5" height="5" fill="none" stroke="#000000" />
    <rect x="2" y="3" width="6" height="1.8" fill="#000000" />
  </svg>
)

const CloseGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <path fill="none" stroke="#000000" strokeWidth="1.8" d="M1 1L9 9M9 1L1 9" />
  </svg>
)

const TitleButton = ({ onClick, children }) => (
  <div className={`flex shrink-0 bg-[#cccccc] active:bg-[#b4b4b4] border-t-${edge} border-l-${edge} border-white active:border-[#808080]`} onClick={onClick}>
    <div className={`flex items-center justify-center w-[${px(20)}] h-[${px(18)}] border-b-${edge} border-r-${edge} border-[#808080] active:border-white`}>
      {children}
    </div>
  </div>
)

// A window's title bar: dark blue in front, grey behind, the title in the middle.
// The icon at its left opens the system menu (`onMenu`); a scene's has the gear
// that opens its settings (`onSettings`), and a window that can fill the desktop
// the maximize button.
const TitleBar = ({ title, icon, active = true, maximized = false, onMenu, onSettings, onHide, onMaximize, onClose, ...drag }) => (
  <div
    className={`flex items-center shrink-0 h-[${px(24)}] gap-[${px(2)}] px-[${px(2)}] ${active ? `bg-[${TITLE}] text-white` : 'bg-[#cccccc] text-[#5a5a5a]'}`}
    {...drag}
  >
    <div className={`flex items-center justify-center shrink-0 w-[${px(20)}] h-[${px(20)}]`} onClick={onMenu}>
      {icon}
    </div>
    <div className={`flex flex-1 basis-0 min-w-0 justify-center px-[${px(4)}]`}>
      <span className="min-w-0 truncate font-bold">{title}</span>
    </div>
    {onSettings ? (
      <TitleButton onClick={onSettings}>
        <GearGlyph />
      </TitleButton>
    ) : null}
    <TitleButton onClick={onHide}>
      <HideGlyph />
    </TitleButton>
    {onMaximize ? <TitleButton onClick={onMaximize}>{maximized ? <RestoreGlyph /> : <MaxGlyph />}</TitleButton> : null}
    <TitleButton onClick={onClose}>
      <CloseGlyph />
    </TitleButton>
  </div>
)

// A window's frame: a dark line, a bevel and two pixels of grey, the sizing
// border. `className` places it; `frame` are its own handlers (a press on the
// border sizes it).
const Frame = ({ className = '', frame = {}, children }) => (
  <div className={`flex flex-col bg-[#cccccc] border-[${edge}px] border-[#404040] ${className}`} {...frame}>
    <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-white`}>
      <div className={`flex flex-col flex-1 min-h-0 gap-[${px(2)}] p-[${px(2)}] border-b-${edge} border-r-${edge} border-[#808080]`}>
        {children}
      </div>
    </div>
  </div>
)

// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Signal({ rssi }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${px(2)}] h-[${px(14)}]`}>
      {[5, 8, 11, 14].map((height, i) => (
        <div className={`w-[${px(3)}] h-[${px(height)}] ${i < level ? 'bg-black' : 'bg-[#808080]'}`} />
      ))}
    </div>
  )
}

function Battery({ percent }) {
  if (typeof percent !== 'number') return null
  return (
    <svg viewBox="0 0 22 12" className={`w-[${px(22)}] h-[${px(12)}]`}>
      <rect x="0.5" y="0.5" width="18" height="11" fill="none" stroke="#000000" />
      <rect x="19" y="4" width="3" height="4" fill="#000000" />
      <rect x="2" y="2" width={(15 * percent) / 100} height="8" fill={percent > 15 ? '#22b14c' : '#c00000'} />
    </svg>
  )
}

// The WarpCenter's right end: what the frame knows of itself, the date and the
// clock. It opens System Setup.
const Monitor = ({ app, now, wide, onClick }) => (
  <Sunken className="shrink-0 active:bg-[#b4b4b4]" onClick={onClick}>
    <Signal rssi={app.frame.wifiRssi} />
    <Battery percent={app.frame.batteryPercent} />
    {wide ? <span className="whitespace-nowrap">{date(now)}</span> : null}
    <span className="whitespace-nowrap font-bold">{clock(now, on(app.state.twentyFourHour))}</span>
  </Sunken>
)

// The WarpCenter: a grey bar along the top.
const Center = ({ className = '', children }) => (
  <div className={`flex flex-col shrink-0 h-[${barH()}px] bg-[#cccccc] border-b-${edge} border-[#404040] ${className}`} onPointerDown={() => {}}>
    <div className={`flex flex-1 min-h-0 items-stretch gap-[${px(3)}] px-[${px(3)}] py-[${px(2)}] border-t-${edge} border-white`}>{children}</div>
  </div>
)

// ---------------------------------------------------------------- the menus
//
// A menu's items are {label, icon, onClick, check, dim, keys}, a rule is null,
// and {heading} names the group of items under it.
const rowH = (item) => (item === null ? size(8) : item.heading ? size(18) : size(22))

const Rule = () => (
  <div className={`flex flex-col justify-center shrink-0 h-[${size(8)}px] px-[${px(3)}]`}>
    <div className={`h-[${edge}px] bg-[#808080]`} />
    <div className={`h-[${edge}px] bg-white`} />
  </div>
)

const rows = (items) =>
  items.map((item) =>
    item === null ? (
      <Rule />
    ) : item.heading ? (
      <div className={`flex items-center shrink-0 h-[${size(18)}px] px-[${px(8)}] text-[${px(12)}] font-bold text-[#4c4c4c]`}>
        <span className="flex-1 min-w-0 truncate">{item.heading}</span>
      </div>
    ) : (
      <div
        className={`flex items-center shrink-0 h-[${size(22)}px] gap-[${px(5)}] pl-[${px(4)}] pr-[${px(8)}] ${item.dim ? 'text-[#808080]' : ''} hover:bg-[${TITLE}] hover:text-white`}
        onClick={item.onClick}
      >
        <div className={`flex items-center justify-center shrink-0 w-[${size(12)}px]`}>{item.check ? <Check /> : null}</div>
        {item.icon ? <div className="flex shrink-0">{item.icon}</div> : null}
        <span className="flex-1 min-w-0 truncate">{item.label}</span>
        {item.keys ? <span className={`shrink-0 text-[${px(11)}]`}>{item.keys}</span> : null}
      </div>
    ),
  )

// A menu at x, y (or with its bottom at `bottom`), `w` wide and `maxH` high at
// most: `head` and `foot` stay, `body` scrolls where all of it does not fit. It
// takes a press itself: the cover under it closes it on a press, and a render
// before the release would take the item away from its click.
function Popup({ x, y, bottom, w, maxH, head = [], body = [], foot = [] }) {
  const sum = (items) => items.reduce((n, item) => n + rowH(item), 0)
  const h = Math.max(size(22), Math.min(maxH, 4 * edge + size(4) + sum(head) + sum(body) + sum(foot)))
  const top = typeof bottom === 'number' ? bottom - h : y
  return (
    <div
      className={`absolute left-[${x}px] top-[${top}px] w-[${w}px] h-[${h}px] flex flex-col bg-[#cccccc] border-[${edge}px] border-[#404040]`}
      onPointerDown={() => {}}
    >
      <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-white`}>
        <div className={`flex flex-col flex-1 min-h-0 py-[${px(2)}] border-b-${edge} border-r-${edge} border-[#808080]`}>
          {rows(head)}
          <div className="flex flex-col flex-1 min-h-0 overflow-y-auto">{rows(body)}</div>
          {rows(foot)}
        </div>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene, and
// is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min, snap}, in the desktop's pixels (x to
// h is the window's own box, kept while it fills the desktop or is snapped to a
// half of it, `snap` 'l' or 'r'; `min` hidden, in the Window List alone; a
// built-in scene's also its `title`); `boxes`, where each scene's window was when
// it closed, by scene id; `last`, the scene that had the focus at the last
// render; `asked`, the scene this layout last brought forward itself; `gone`, the
// scene whose window was just closed; `menu`, the menu open ('scenes', 'windows',
// 'sys' for the window `sysOf`, 'popup' at `popupAt`, 'drawer'); `picked`, the
// desktop icons picked; `band` and `iconDrag`, a rectangle being drawn around
// icons and icons being dragged; `full`, `peek` and `drag`, a move or a size in
// progress. Kept on disk, in a field: `iconSpots`, where the icons are.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, size(160))
  const minH = Math.min(deskH, size(100))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = size(48)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - size(24))))
  return win
}

// The windows' boxes are in the desktop's pixels, and the desktop is the
// panel over the render scale: a new scale, a turn or a resized browser window
// gives it another size, and boxes made for the old one sat small in a corner
// or off the glass (2026-11-16). `room` is the desktop they were made for; on
// another, each window, and each closed one's box, keeps its place and size as
// a share of the desktop.
function refit(app, wins, fresh, deskW, deskH) {
  const room = app.state.room
  if (room && room.w === deskW && room.h === deskH) return wins
  frameos.setState('room', { w: deskW, h: deskH })
  if (fresh || !room || !(room.w > 0 && room.h > 0)) return wins
  const fit = (b) =>
    clamp({ ...b, x: (b.x * deskW) / room.w, y: (b.y * deskH) / room.h, w: (b.w * deskW) / room.w, h: (b.h * deskH) / room.h }, deskW, deskH)
  const boxes = {}
  for (const [id, box] of Object.entries(boxesOf(app))) if (box) boxes[id] = fit(box)
  frameos.setState('boxes', boxes)
  const fitted = wins.map((w) => (w ? fit(w) : w))
  frameos.setState('wins', fitted)
  return fitted
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window, in a desktop's pixels like every size
// here: its own size where it says one (`windowSize` in app.frame.scenes, its
// settings.windowSize, `WxH`), with `own` set, else 800 x 480, a 7.5-inch
// frame's. Every desktop of windows has this same function.
function ownSize(app, id) {
  const scene = Array.isArray(app.frame.scenes) ? app.frame.scenes.find((s) => s.id === id) : null
  const mine = scene ? /^(\d+)x(\d+)$/.exec(String(scene.windowSize || '')) : null
  const w = mine ? Number(mine[1]) : 800
  const h = mine ? Number(mine[2]) : 480
  return { w: Math.round(w * zoom), h: Math.round(h * zoom), own: !!mine }
}

// Where a new window w by h goes in `area` ({x, y, w, h}): all of it on bare
// desktop where it fits, clear of the windows shown (`shown`, their boxes) and of
// what the desktop keeps clear (`clear`: its icons). Where nothing is free, off
// the icons if it can be, then where it covers the least of the windows, a title
// bar (`bar` high) counting five times over, so no window opens right over
// another's title bar. The spots tried are the area's corners and thirds, `gap`
// beside each box and a title bar down from each window, each a sum over the
// boxes: a few hundred with a few windows open, and only when one opens, cheap
// enough for an ESP32. The highest free spot wins, then the leftmost. Every
// desktop of windows has this same function (docs/scene-layouts.md "Windows").
function freeSpot(w, h, area, shown, clear, bar, gap) {
  // `gap` from the area's edges too, where the window leaves room for it.
  const roomX = Math.max(0, area.w - w)
  const roomY = Math.max(0, area.h - h)
  const left = area.x + Math.min(gap, roomX / 2)
  const top = area.y + Math.min(gap, roomY / 2)
  const right = area.x + roomX - Math.min(gap, roomX / 2)
  const bottom = area.y + roomY - Math.min(gap, roomY / 2)
  const xs = []
  const ys = []
  const put = (list, v, lo, hi) => {
    const at = Math.round(Math.max(lo, Math.min(v, hi)))
    if (list.indexOf(at) < 0) list.push(at)
  }
  for (let i = 0; i <= 3; i++) {
    put(xs, left + ((right - left) * i) / 3, left, right)
    put(ys, top + ((bottom - top) * i) / 3, top, bottom)
  }
  for (const b of shown.concat(clear)) {
    put(xs, b.x + b.w + gap, left, right)
    put(xs, b.x - w - gap, left, right)
    put(ys, b.y + b.h + gap, top, bottom)
    put(ys, b.y - h - gap, top, bottom)
  }
  for (const b of shown) {
    put(xs, b.x + bar, left, right)
    put(ys, b.y + bar, top, bottom)
  }
  xs.sort((a, b) => a - b)
  ys.sort((a, b) => a - b)
  // How much of a box's top `down` pixels a window at x, y covers.
  const covered = (x, y, b, down) => {
    const across = Math.min(x + w, b.x + b.w) - Math.max(x, b.x)
    const deep = Math.min(y + h, b.y + down) - Math.max(y, b.y)
    return across > 0 && deep > 0 ? across * deep : 0
  }
  let best = null
  for (const y of ys)
    for (const x of xs) {
      let icons = 0
      for (const b of clear) icons += covered(x, y, b, b.h)
      let cost = 0
      for (const b of shown) cost += covered(x, y, b, b.h) + 4 * covered(x, y, b, Math.min(bar, b.h))
      if (icons === 0 && cost === 0) return { x, y }
      if (!best || icons < best.icons || (icons === best.icons && cost < best.cost)) best = { x, y, icons, cost }
    }
  return { x: best.x, y: best.y }
}

// What a window's frame takes around its scene: the borders, the title bar and
// the gap under it.
const chromeW = () => 4 * edge + size(4)
const chromeH = () => 4 * edge + size(30)

function placed(app, id, wins, deskW, deskH, clear) {
  const win = { id, z: topZ(wins) + 1 }
  // Where it was when it closed, if it was open before.
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, deskW, deskH)
  // Otherwise its scene's size, its borders and title bar around it, all of it
  // on the desktop and as little of it as can be over the windows open, the
  // icons and the LaunchPad (freeSpot).
  const own = ownSize(app, id)
  const shown = wins.filter((other) => !other.min)
  // A scene's own size that does not fit is made smaller, its shape kept, once
  // another window is open: the first one still fills the desktop, below.
  const room = own.own ? Math.min((deskW - chromeW()) / own.w, (deskH - chromeH()) / own.h) : 1
  const shrink = room >= 1 || !shown.length ? 1 : 0.85 * room
  const w = Math.round(own.w * shrink) + chromeW()
  const h = Math.round(own.h * shrink) + chromeH()
  // Where it does not fit, the first window fills the desktop, which is what the
  // frame looked like before anything else was opened, and the next ones take
  // most of it.
  const fits = w <= deskW && h <= deskH
  const box = fits ? { w, h } : { w: Math.round(deskW * 0.62), h: Math.round(deskH * 0.62) }
  const boxes = shown.map((other) => boxOf(other, deskW, deskH))
  const at = freeSpot(box.w, box.h, { x: 0, y: 0, w: deskW, h: deskH }, boxes, clear, Math.round(28 * zoom), Math.round(8 * zoom))
  return clamp({ ...win, ...at, ...box, max: !fits && !shown.length }, deskW, deskH)
}

// Where each window is, for a desktop chosen in this one's place (`openPlaces`,
// handed over with `openScenes`): by scene id, its box as a share of the whole
// picture, so a desktop whose bars are elsewhere puts it where it was on the glass.
const share = (v) => Math.round(v * 10000) / 10000
function keepPlaces(app, wins, desk, width, height) {
  const places = {}
  for (const w of wins)
    places[w.id] = {
      x: share((desk.x + w.x) / width), y: share((desk.y + w.y) / height),
      w: share(w.w / width), h: share(w.h / height),
      max: !!w.max, snap: w.snap || null, min: !!w.min,
    }
  if (JSON.stringify(places) !== JSON.stringify(app.state.openPlaces || {})) frameos.setState('openPlaces', places)
}
function carriedPlace(app, id, desk, width, height) {
  const p = app.state.openPlaces && app.state.openPlaces[id]
  if (!p || ![p.x, p.y, p.w, p.h].every((v) => typeof v === 'number' && isFinite(v))) return null
  const snap = p.snap === 'l' || p.snap === 'r' ? p.snap : undefined
  return { x: p.x * width - desk.x, y: p.y * height - desk.y, w: p.w * width, h: p.h * height, max: p.max === true, snap, min: p.min === true }
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// window each, where it was there (`openPlaces`), or where there is room
// (freeSpot), in that order, so the one that had the focus is on top.
function opened(app, names, titleOf, deskW, deskH, desk, width, height, clear) {
  const wins = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id !== 'string' || wins.some((w) => w.id === id) || !(names[id] || isSystem(id))) continue
    const there = carriedPlace(app, id, desk, width, height)
    const win = there ? clamp({ ...there, id, z: topZ(wins) + 1 }, deskW, deskH) : placed(app, id, wins, deskW, deskH, clear)
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// Where a window is drawn: its own box, the whole desktop, or a half of it.
function boxOf(win, deskW, deskH) {
  const half = Math.round(deskW / 2)
  if (win.max) return { x: 0, y: 0, w: deskW, h: deskH }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: deskH }
  if (win.snap === 'r') return { x: half, y: 0, w: deskW - half, h: deskH }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// Where the LaunchPad sits: the middle of the desktop's bottom, `count` buttons
// wide; null where it is turned off or the desktop has no room for it.
function launchPadOf(app, count, deskW, deskH) {
  if (app.state.showLaunchPad === false || app.state.showLaunchPad === 'false') return null
  const w = 2 * edge + size(8) + count * size(56) + (count - 1) * size(4)
  const h = 2 * edge + size(8) + size(12) + size(50)
  if (w > deskW - size(16) || h * 3 > deskH) return null
  return { x: Math.round((deskW - w) / 2), y: deskH - h - size(8), w, h }
}

// What a press, a key or a menu does to the windows. Each one reads the state
// afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const focus = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: false }))
    if (id !== current) go(id)
  }
  const open = (id) => {
    frameos.setState('menu', null)
    frameos.setState('picked', null)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its window, and the scene window on top comes forward to open it over;
  // with none, the built-in one goes back where it came from, its window closed.
  // Either way the focus is this layout's doing (`asked`): one left open keeps its
  // window.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    const top = winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
    if (top) return go(top.id)
    // None: it goes back, done, and its window with it.
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== now))
    frameos.dispatch(commandOf(now))
  }
  // A scene's settings, from the gear on its title bar or its system menu: a
  // window of their own, opened over the scene's window brought forward first;
  // open already, that window comes forward as it was left.
  const sceneSettings = (id) => {
    frameos.setState('menu', null)
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // A built-in scene of the frame's, one window each: System Setup (the frame's
  // page) and the scene list. Open already, it comes forward as it was left.
  const builtIn = (id, command, payload) => () => {
    frameos.setState('menu', null)
    frameos.setState('picked', null)
    if (windowOf(id)) return focus(id)
    overAScene()
    frameos.dispatch(command, payload)
    frameos.setState('asked', id)
  }
  const controlPanel = builtIn(SETTINGS, 'sceneSettings', { page: 'frame' })
  const sceneList = builtIn(SWITCHER, 'sceneSwitcher', {})
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id, skip = [id]) =>
    winsOf(app)
      .filter((w) => !skip.includes(w.id) && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  // Hidden, a window is in the Window List alone.
  const minimize = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // A window closed, a scene's settings with it. The one in front: the next one
  // down takes the focus, as when it is put away, whatever scene it was opened
  // from. With none left the desktop is bare: a scene stays the frame's with no
  // window, and a built-in one goes back as its own Cancel does, the scene it
  // lands on opening no window either (app.frame.wentBack).
  const close = (id) => {
    frameos.setState('menu', null)
    const ids = isSystem(id) ? [id] : [id, settingsOf(id)]
    const front = ids.includes(current)
    const next = front ? nextAfter(current, ids) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => !ids.includes(w.id)))
    if (!front) return
    frameos.setState('full', false)
    if (next) return go(next.id)
    frameos.setState('gone', current)
    if (isSystem(current)) frameos.dispatch(commandOf(current))
  }
  const toggleMax = (id) => {
    frameos.setState('menu', null)
    update(id, (w) => ({ max: !w.max, snap: null }))
  }
  const restore = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ max: false, snap: null, min: false }))
  }
  const showAll = () => {
    frameos.setState('menu', null)
    frameos.setState('wins', winsOf(app).map((w) => ({ ...w, min: false })))
  }
  const toggleFull = () => {
    frameos.setState('menu', null)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // A menu of the WarpCenter's, the LaunchPad's drawer: one press opens it, the
  // next closes it.
  const toggleMenu = (id) => () => {
    frameos.setState('picked', null)
    frameos.setState('menu', app.state.menu === id ? null : id)
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  return {
    update, focus, open, sceneSettings, controlPanel, sceneList, minimize, close, toggleMax, restore, showAll,
    toggleFull, toggleMenu, cycle,
  }
}

// A built-in scene's window has System Setup's folder or the scenes' folder, the
// frame's own apps this desktop's drawings of them (the store's bag, Files'
// drive, the terminal's prompt) even when they have an icon of their own, a scene
// with an icon of its own that one (ownIcon), and the others the window.
let storeId = null
let filesId = null
let terminalId = null
let frameScenes = []
function iconOf(id, s = 16) {
  if (id === SWITCHER) return <FolderIcon s={s} />
  if (isSystem(id)) return <SetupIcon s={s} />
  if (id === storeId) return <StoreIcon s={s} />
  if (id === filesId) return <DriveIcon s={s} />
  if (id === terminalId) return <PromptIcon s={s} />
  return ownIcon(frameScenes.find((scene) => scene.id === id), px(s)) || <WindowIcon s={s} />
}

// What a built-in scene's window is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} - Settings`
  return id === SWITCHER ? 'Scenes - Icon View' : 'System Setup'
}

// What a built-in scene's window is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} - Settings`
  if (app.frame.sceneId === SWITCHER) return 'Scenes - Icon View'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'System Setup'
  if (page === 'Layout settings') return 'Desktop - Settings'
  return app.state.openedOver ? `${app.state.openedOver} - Settings` : 'Settings'
}

// ------------------------------------------------------------ the desktop's icons
//
// The icons stand on a grid: `cells` are the places an icon can go, each {key,
// x, y} (its box's corner on the desktop), in the order icons fill them. An icon
// dragged stays where it was let go: from the first drag on, the layout keeps
// every icon's cell by its id in `iconSpots`, a field kept on disk. An icon keeps
// its cell while the grid has it and no icon before it took it; the others take
// the first free cells in order, so a desktop no icon was ever dragged on has
// its columns as it always had, and an icon new to it (the store installed)
// takes a cell no other has. Every desktop with icons has these same functions
// (docs/scene-layouts.md "Windows", its "Icons").
function arranged(ids, spots, cells) {
  const at = {}
  const taken = {}
  const byKey = {}
  for (const cell of cells) byKey[cell.key] = cell
  for (const id of ids) {
    const cell = byKey[spots[id]]
    if (cell && !taken[cell.key]) {
      at[id] = cell
      taken[cell.key] = true
    }
  }
  let next = 0
  for (const id of ids) {
    if (at[id]) continue
    while (next < cells.length - 1 && taken[cells[next].key]) next++
    at[id] = cells[next]
    taken[cells[next].key] = true
  }
  return at
}

// The icons' cells kept (`iconSpots`: a field on disk comes back as its text).
function spotsOf(app) {
  let spots = app.state.iconSpots
  if (typeof spots === 'string') {
    try {
      spots = JSON.parse(spots)
    } catch (e) {
      spots = null
    }
  }
  return spots && typeof spots === 'object' && !Array.isArray(spots) ? spots : {}
}

// The icons picked (`picked`, their ids; before 2026.11.28 one id, or null).
function pickedOf(app) {
  const picked = app.state.picked
  return Array.isArray(picked) ? picked : typeof picked === 'string' ? [picked] : []
}

// The icons a rectangle drawn on the desktop touches (`band`, from x0, y0 to
// x1, y1 either way round), each icon's box `w` by `h` from its cell's corner.
function banded(band, at, w, h) {
  const left = Math.min(band.x0, band.x1)
  const top = Math.min(band.y0, band.y1)
  const right = Math.max(band.x0, band.x1)
  const bottom = Math.max(band.y0, band.y1)
  return Object.keys(at).filter((id) => {
    const cell = at[id]
    return cell.x < right && cell.x + w > left && cell.y < bottom && cell.y + h > top
  })
}

// Where icons dragged `dx`, `dy` go (`moving`, the one held first): each to the
// free cell nearest where it was let go, the others staying where they are.
// What comes back is every icon's cell, the new `iconSpots`.
function dropped(at, moving, dx, dy, cells) {
  const spots = {}
  const taken = {}
  for (const id of Object.keys(at)) {
    spots[id] = at[id].key
    if (!moving.includes(id)) taken[at[id].key] = true
  }
  for (const id of moving) {
    const from = at[id]
    if (!from) continue
    let best = from
    let far = Infinity
    for (const cell of cells) {
      if (taken[cell.key]) continue
      const ax = cell.x - from.x - dx
      const ay = cell.y - from.y - dy
      if (ax * ax + ay * ay < far) {
        far = ax * ax + ay * ay
        best = cell
      }
    }
    taken[best.key] = true
    spots[id] = best.key
  }
  return spots
}

// What a new window keeps clear of: each column of icons, from its top icon to
// its bottom one (the icons' boxes `w` by `h`).
function iconColumns(at, w, h) {
  const columns = {}
  for (const id of Object.keys(at)) {
    const cell = at[id]
    const box = columns[cell.x]
    if (!box) {
      columns[cell.x] = { x: cell.x, y: cell.y, w, h }
      continue
    }
    const bottom = Math.max(box.y + box.h, cell.y + h)
    box.y = Math.min(box.y, cell.y)
    box.h = bottom - box.y
  }
  return Object.keys(columns).map((x) => columns[x])
}

// What the pointer does on the desktop and its icons (`at`, `w`, `h` and `cells`
// as above; `slop`, how far a press goes before it drags an icon). On bare
// desktop (`desk`) a press that moves draws a rectangle (`band`, drawn by Band)
// and picks every icon it touches, those picked before kept with Ctrl or Shift,
// and a click there picks none. A press on an icon (`icon(id, go)`) picks it,
// with Ctrl or Shift one more (or one less), and dragged it moves every icon
// picked (`iconDrag`, its `dx`, `dy`), each let go into the free cell nearest
// (dropped). A click on one picks it alone, a double click opens it (`go`). A
// press lost without its release (a `pointerCancel`) lets go: the rectangle
// goes, and icons being dragged stay where they were. A move with nothing held
// asks for no render: a mouse passing over draws nothing, unless a rectangle or
// a drag is still going, whose release never came. Nor does a press on a slow
// panel (e-paper): its click or its first move draws what it did, one refresh
// and not two.
function iconPointer(app, at, w, h, cells, slop) {
  const scale = app.frame.scale || 1
  const more = (e) => e.ctrl === true || e.shift === true || e.meta === true
  const pressed = app.frame.fast === false ? false : undefined
  const desk = {
    onPointerDown: (e) => {
      if (e.button > 0) return false
      const keep = more(e) ? pickedOf(app) : []
      frameos.setState('band', { x0: e.localX, y0: e.localY, x1: e.localX, y1: e.localY, keep })
      frameos.setState('picked', keep)
      return pressed
    },
    onPointerMove: (e) => {
      const band = app.state.band
      if (!e.buttons) {
        // A runtime before 2026.11.17 hands no element a lost press: it ends
        // at the next move over the desktop.
        if (!band && !app.state.iconDrag) return false
        frameos.setState('band', null)
        frameos.setState('iconDrag', null)
        return
      }
      if (!band) return false
      const next = { ...band, x1: e.localX, y1: e.localY }
      const keep = Array.isArray(band.keep) ? band.keep : []
      frameos.setState('band', next)
      frameos.setState('picked', keep.concat(banded(next, at, w, h).filter((id) => !keep.includes(id))))
    },
    onPointerUp: () => {
      const band = app.state.band
      if (!band) return false
      frameos.setState('band', null)
      // One that never moved was never drawn.
      if (band.x1 === band.x0 && band.y1 === band.y0) return false
    },
    onClick: (e) => {
      if (!more(e)) frameos.setState('picked', [])
    },
  }
  const icon = (id, go) => ({
    onPointerDown: (e) => {
      if (e.button > 0) return false
      const picked = pickedOf(app)
      const next = !more(e)
        ? picked.includes(id)
          ? picked
          : [id]
        : picked.includes(id)
          ? picked.filter((other) => other !== id)
          : picked.concat([id])
      frameos.setState('picked', next)
      frameos.setState('iconDrag', next.includes(id) ? { id, x: e.x, y: e.y, dx: 0, dy: 0, on: false } : null)
      return pressed
    },
    onPointerMove: (e) => {
      const drag = app.state.iconDrag
      if (!drag || drag.id !== id || !e.buttons) return false
      const dx = (e.x - drag.x) / scale
      const dy = (e.y - drag.y) / scale
      if (!drag.on && Math.abs(dx) + Math.abs(dy) < slop) return false
      frameos.setState('iconDrag', { ...drag, dx, dy, on: true })
    },
    onPointerUp: (e) => {
      const drag = app.state.iconDrag
      if (!drag) return false
      frameos.setState('iconDrag', null)
      if (!drag.on) return false
      // A press lost on the way (pointerCancel): they stay where they were.
      if (e.type !== 'pointerUp') return
      const moving = [id].concat(pickedOf(app).filter((other) => other !== id))
      frameos.setState('iconSpots', dropped(at, moving, drag.dx, drag.dy, cells))
    },
    onClick: (e) => {
      if (!more(e)) frameos.setState('picked', [id])
    },
    onDoubleClick: () => {
      frameos.setState('picked', [])
      go()
    },
  })
  // How far an icon is drawn from its cell: the icons picked follow a drag.
  const drag = app.state.iconDrag
  const picked = pickedOf(app)
  const offset = (id) => (drag && drag.on && picked.includes(id) ? { x: Math.round(drag.dx), y: Math.round(drag.dy) } : { x: 0, y: 0 })
  return { desk, icon, picked, offset }
}

// The rectangle a drag on bare desktop draws: a dotted line, black on white,
// over the icons and under the windows, as a desktop draws it.
function Band({ band }) {
  if (!band || typeof band.x0 !== 'number') return null
  const x = Math.round(Math.min(band.x0, band.x1))
  const y = Math.round(Math.min(band.y0, band.y1))
  const w = Math.round(Math.abs(band.x1 - band.x0))
  const h = Math.round(Math.abs(band.y1 - band.y0))
  if (w < 2 || h < 2) return null
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px]`}>
      <rect x="0.5" y="0.5" width={w - 1} height={h - 1} fill="none" stroke="#ffffff" />
      <rect x="0.5" y="0.5" width={w - 1} height={h - 1} fill="none" stroke="#000000" strokeDasharray="2 2" />
    </svg>
  )
}

function desktop(app, now, width, height) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const files = filesOf(app)
  const terminal = terminalOf(app)
  storeId = store ? store.id : null
  filesId = files ? files.id : null
  terminalId = terminal ? terminal.id : null
  frameScenes = app.frame.scenes
  const frameApps = [store, files, terminal].filter(Boolean)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  const deskTop = barH()
  const deskW = width
  const deskH = Math.max(1, height - deskTop)
  // The desktop's icons, in columns from the top left (icons()): the scenes'
  // folder, the frame's own apps and System Setup, or where each was dragged to on
  // that grid (arranged), none under the LaunchPad at the bottom. A new window
  // keeps clear of them and of the LaunchPad where it can.
  const iconW = size(84)
  const iconH = size(70)
  const perColumn = Math.max(1, Math.floor((deskH - size(8)) / iconH))
  const iconIds = [SWITCHER, ...frameApps.map((scene) => scene.id), SETTINGS]
  const launch = launchPadOf(app, 3 + frameApps.length, deskW, deskH)
  const grid = []
  const columns = Math.max(Math.floor((deskW - size(8)) / iconW), Math.ceil(iconIds.length / perColumn))
  for (let c = 0; c < columns; c++)
    for (let r = 0; r < perColumn; r++) grid.push({ key: `${c}:${r}`, x: size(8) + c * iconW, y: size(8) + r * iconH })
  const free = launch
    ? grid.filter((b) => b.x >= launch.x + launch.w || b.x + iconW <= launch.x || b.y >= launch.y + launch.h || b.y + iconH <= launch.y)
    : grid
  const cells = free.length >= iconIds.length ? free : grid
  const iconAt = arranged(iconIds, spotsOf(app), cells)
  const clear = iconColumns(iconAt, iconW, iconH)
  if (launch) clear.push(launch)

  // Whatever brought a scene forward (a window, a menu, an icon, the scene list, a
  // button, the API), its window is open and on top, and the one it took the
  // focus from is next below it. A built-in scene's window is named by what it
  // shows while it has the focus, and closes once it has gone back by itself: the
  // focus left it for a scene, and not because this layout moved it. One that
  // opened another (the gear in a scene's settings opening System Setup) did not
  // go back, and stays open.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = refit(app, fresh ? opened(app, names, titleOf, deskW, deskH, { x: 0, y: deskTop }, width, height, clear) : winsOf(app), fresh, deskW, deskH)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id)))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length
  if (current) {
    // The focus only came back here, from a built-in scene that went back by
    // itself (its Close, its Cancel, its timeout): a window closed stays closed
    // and one put away stays away. A scene chosen, from anywhere, opens, and so
    // does the first one a desktop just made shows.
    const quiet = !!app.state.last && app.state.last !== current && app.frame.wentBack === true
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current && !quiet) {
      win = placed(app, current, wins, deskW, deskH, clear)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && win.min && !quiet) win.min = false
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !keptOpen(app, before.id, current)) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (quiet && !win) frameos.setState('gone', current)
      else if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
      // Nothing of its own to show: the window on top takes the focus, as when
      // the one in front is closed.
      if (quiet && (!win || win.min)) {
        const top = wins.filter((w) => !w.min && w.id !== current).sort((a, b) => (b.z || 0) - (a.z || 0))[0]
        if (top) {
          frameos.setState('asked', top.id)
          frameos.dispatch('setCurrentScene', { sceneId: top.id })
        }
      }
    }
  }
  // Where only so many scenes run at once (app.frame.windows, an ESP32's few),
  // one more closes the one that had the focus longest ago, its box kept.
  const most = app.frame.windows
  if (most > 0) {
    const others = wins.filter((w) => !isSystem(w.id) && w.id !== current).sort((a, b) => (a.z || 0) - (b.z || 0))
    const room = most - (current && !isSystem(current) && wins.some((w) => w.id === current) ? 1 : 0)
    const gone = others.slice(0, Math.max(0, others.length - room))
    if (gone.length) {
      const boxes = { ...boxesOf(app) }
      for (const win of gone) {
        const { x, y, w, h, max, snap } = win
        boxes[win.id] = { x, y, w, h, max, snap }
        wins.splice(wins.indexOf(win), 1)
      }
      frameos.setState('boxes', boxes)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  keepPlaces(app, wins, { x: 0, y: deskTop }, width, height)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  const focused = wins.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const menu = app.state.menu || null
  const isOpen = (id) => wins.some((w) => w.id === id)
  const {
    update, focus, open, sceneSettings, controlPanel, sceneList, minimize, close, toggleMax, restore, showAll,
    toggleFull, toggleMenu,
  } = actions(app)

  // A press on a title bar moves the window, one on its border sizes it from
  // that edge; the moves that follow are captured by what was pressed. Let go
  // at the top of the desktop, a moved window fills it, at the left or right
  // edge it takes that half; dragged away again, it has its own size back.
  const startDrag = (drawn, mode) => (e) => {
    frameos.setState('picked', null)
    // As it is now, not as it was drawn: a size may have come since.
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, deskW, deskH)
    const docked = !!(win.max || win.snap)
    // A half sized from its edge is a window of that size from then on.
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale
      const y = e.y / scale - deskTop
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= deskW - 3 ? 'r' : null
      if (drag.docked) {
        // A press that does not move leaves it be (a double click sizes it back).
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        // Its own size, with the pointer as far across the title bar as it was.
        const across = (drag.x / scale - drag.from.x) / drag.from.w
        const from = { x: drag.x / scale - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, deskW, deskH), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  const corner = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner ? 'l' : e.localX > e.width - corner ? 'r' : ''
    const y = e.localY < corner ? 't' : e.localY > e.height - corner ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => toggleMax(win.id),
  })

  // Tile puts the windows not hidden side by side in a grid over the desktop, the
  // one in front first; Cascade down and right from the top left at their own
  // sizes, the one in front last, on top.
  const arrange = (how) => () => {
    frameos.setState('menu', null)
    const all = winsOf(app)
    const order = all
      .filter((w) => !w.min)
      .sort((a, b) => (a.id === current) - (b.id === current) || (a.z || 0) - (b.z || 0))
    if (!order.length) return
    const cols = Math.ceil(Math.sqrt(order.length))
    const lines = Math.ceil(order.length / cols)
    const boxes = {}
    order.forEach((w, i) => {
      if (how === 'tile') {
        const k = order.length - 1 - i
        const c = k % cols
        const r = Math.floor(k / cols)
        const x0 = Math.round((c * deskW) / cols)
        const y0 = Math.round((r * deskH) / lines)
        boxes[w.id] = { x: x0, y: y0, w: Math.round(((c + 1) * deskW) / cols) - x0, h: Math.round(((r + 1) * deskH) / lines) - y0 }
      } else {
        const step = size(26) * (i % 8)
        const x = size(24) + step
        const y = size(12) + step
        boxes[w.id] = { x, y, w: Math.min(w.w, deskW - x), h: Math.min(w.h, deskH - y) }
      }
    })
    frameos.setState(
      'wins',
      all.map((w) => (boxes[w.id] ? clamp({ ...w, ...boxes[w.id], max: false, snap: null }, deskW, deskH) : w)),
    )
  }

  const windowOf = (win) => {
    const active = win.id === current
    const box = boxOf(win, deskW, deskH)
    return (
      <Frame
        className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px]${win.max ? '' : ` cursor-resize-[${corner}px]`}`}
        frame={win.max ? { onPointerDown: () => false } : sizing(win)}
      >
        <TitleBar
          title={names[win.id]}
          icon={iconOf(win.id)}
          active={active}
          maximized={win.max}
          onMenu={() => {
            frameos.setState('sysOf', win.id)
            frameos.setState('menu', 'sys')
          }}
          onSettings={isSystem(win.id) ? undefined : () => sceneSettings(win.id)}
          onHide={() => minimize(win.id)}
          onMaximize={() => toggleMax(win.id)}
          onClose={() => close(win.id)}
          {...moving(win)}
        />
        <div className="relative flex flex-col flex-1 min-h-0">
          {active ? <yield /> : hidden.has(win.id) ? null : <Scene id={win.id} />}
          {/* A press on a window behind brings it forward, and is only that. */}
          {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
        </div>
      </Frame>
    )
  }

  // Where a window let go now would go: its outline, four bars, over the windows.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, deskW, deskH)
    const t = Math.max(2, size(3))
    const bar = (x, y, w, h) => <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${h}px] bg-[#404040]`} />
    return [bar(b.x, b.y, b.w, t), bar(b.x, b.y + b.h - t, b.w, t), bar(b.x, b.y, t, b.h), bar(b.x + b.w - t, b.y, t, b.h)]
  }

  // The frame's own apps as icons, in columns from the top left: the scenes'
  // folder, the store, Files and the terminal where the frame has them, and
  // System Setup. A click picks one, a double click opens it, a rectangle drawn
  // around some picks those, and a drag moves what is picked (iconPointer); a
  // right click on one opens the desktop's pop-up menu where it is.
  const point = iconPointer(app, iconAt, iconW, iconH, cells, size(8))
  const icons = () => {
    const items = [
      { id: SWITCHER, label: 'Scenes', icon: <FolderIcon />, go: sceneList },
      ...frameApps.map((scene) => ({ id: scene.id, label: names[scene.id], icon: iconOf(scene.id, 32), go: () => open(scene.id) })),
      { id: SETTINGS, label: 'System Setup', icon: <SetupIcon />, go: controlPanel },
    ]
    return items.map((item) => {
      const cell = iconAt[item.id]
      const off = point.offset(item.id)
      const picked = point.picked.includes(item.id)
      const press = point.icon(item.id, item.go)
      return (
        <div
          className={`absolute left-[${cell.x + off.x}px] top-[${cell.y + off.y}px] w-[${iconW}px] h-[${iconH}px] flex flex-col items-center gap-[${px(4)}]`}
          {...press}
          onPointerDown={(e) =>
            e.button === 1 ? popupAt({ localX: cell.x + e.localX, localY: cell.y + e.localY }) : press.onPointerDown(e)
          }
        >
          {item.icon}
          <span className={`max-w-[${iconW}px] px-[${px(2)}] truncate text-white text-[${px(12)}] ${picked ? `bg-[${TITLE}]` : ''}`}>
            {item.label}
          </span>
        </div>
      )
    })
  }

  // The LaunchPad: a button each for the Window List, the scenes (with the arrow
  // to their drawer over it), the frame's own apps and System Setup.
  const launchButtons = launch
    ? [
        { label: 'Windows', icon: <WindowsGlyph s={24} />, go: toggleMenu('windows') },
        { label: 'Scenes', icon: <FolderIcon s={24} />, go: sceneList, drawer: true },
        ...frameApps.map((scene) => ({
          label: scene === store ? 'Store' : scene === files ? 'Files' : 'Terminal',
          icon: iconOf(scene.id, 24),
          go: () => open(scene.id),
        })),
        { label: 'Setup', icon: <SetupIcon s={24} />, go: controlPanel },
      ]
    : []
  const launchPad = () =>
    launch ? (
      <div
        className={`absolute left-[${launch.x}px] top-[${launch.y}px] w-[${launch.w}px] h-[${launch.h}px] flex bg-[#cccccc] border-t-${edge} border-l-${edge} border-white`}
        onPointerDown={() => {}}
      >
        <div className={`flex flex-1 gap-[${px(4)}] p-[${px(4)}] border-b-${edge} border-r-${edge} border-[#404040]`}>
          {launchButtons.map((button) => (
            <div className={`flex flex-col shrink-0 w-[${size(56)}px]`}>
              {button.drawer ? (
                <div className={`flex items-center justify-center shrink-0 h-[${size(12)}px] active:bg-[#b4b4b4]`} onClick={toggleMenu('drawer')}>
                  <Caret up />
                </div>
              ) : (
                <div className={`shrink-0 h-[${size(12)}px]`} />
              )}
              <Raised className={`h-[${size(50)}px]`} onClick={button.go}>
                <div className="flex flex-col items-center min-w-0">
                  {button.icon}
                  <span className={`max-w-[${size(48)}px] truncate text-[${px(10)}]`}>{button.label}</span>
                </div>
              </Raised>
            </div>
          ))}
        </div>
      </div>
    ) : null

  // The WarpCenter: the Desktop menu, the Window List, the frame's own apps in
  // its tray, and what the frame knows of itself with the date and the clock.
  const buttonW = size(44)
  const center = (className) => (
    <Center className={className}>
      <Toggle pressed={menu === 'scenes'} className={`shrink-0 w-[${buttonW}px]`} onClick={toggleMenu('scenes')}>
        <DesktopGlyph />
        <Caret />
      </Toggle>
      <Toggle pressed={menu === 'windows'} className={`shrink-0 w-[${buttonW}px]`} onClick={toggleMenu('windows')}>
        <WindowsGlyph />
        <Caret />
      </Toggle>
      {frameApps.length ? <Etch /> : null}
      {frameApps.map((scene) => (
        <Toggle pressed={!!focused && focused.id === scene.id} className="shrink-0" onClick={() => open(scene.id)}>
          {iconOf(scene.id)}
        </Toggle>
      ))}
      <div className="flex-1" />
      <Monitor app={app} now={now} wide={width >= size(560)} onClick={controlPanel} />
    </Center>
  )

  // The menus. The Desktop menu: the frame's own apps, its scenes by category
  // (scrolling where they are more than the screen), the scenes' folder, Full
  // screen and System Setup.
  const below = deskTop - edge
  const menuMax = Math.max(size(48), height - below - size(4))
  const sceneItem = (scene) => ({
    label: scene.name || scene.id,
    icon: ownIcon(scene, px(16)) || <WindowIcon />,
    onClick: () => open(scene.id),
    check: isOpen(scene.id),
  })
  const sceneRows = () =>
    grouped(programs).flatMap((group) => [...(group.title ? [{ heading: group.title }] : []), ...group.scenes.map(sceneItem)])
  const scenesMenu = () => (
    <Popup
      x={size(3)}
      y={below}
      w={Math.min(width - size(6), size(250))}
      maxH={menuMax}
      head={[
        ...frameApps.map((scene) => ({ label: names[scene.id], icon: iconOf(scene.id), onClick: () => open(scene.id), check: isOpen(scene.id) })),
        ...(frameApps.length ? [null] : []),
      ]}
      body={sceneRows()}
      foot={[
        null,
        { label: 'Scenes - Icon View', icon: <FolderIcon s={16} />, onClick: sceneList },
        { label: full ? 'Exit full screen' : 'Full screen', icon: <MaxGlyph />, onClick: toggleFull, dim: !focused, keys: 'F11' },
        { label: 'System Setup', icon: <SetupIcon s={16} />, onClick: controlPanel },
      ]}
    />
  )
  // The Window List: every window, hidden ones too (grey), the one in front
  // checked; a click brings one forward. Tile, Cascade and Show all under them.
  const windowList = () => (
    <Popup
      x={Math.min(size(3) + buttonW + size(3), Math.max(0, width - size(250)))}
      y={below}
      w={Math.min(width - size(6), size(244))}
      maxH={menuMax}
      body={
        wins.length
          ? wins.map((win) => ({
              label: win.min ? `${names[win.id]} (hidden)` : names[win.id],
              icon: iconOf(win.id),
              onClick: () => focus(win.id),
              check: win.id === current && !win.min,
              dim: !!win.min,
            }))
          : [{ label: 'No windows open', dim: true }]
      }
      foot={[
        null,
        { label: 'Tile', onClick: arrange('tile'), dim: !wins.some((w) => !w.min) },
        { label: 'Cascade', onClick: arrange('cascade'), dim: !wins.some((w) => !w.min) },
        { label: 'Show all', onClick: showAll, dim: !wins.some((w) => w.min) },
      ]}
    />
  )
  // A window's system menu, under the icon at its title bar's left.
  const sysMenu = () => {
    const win = wins.find((w) => w.id === app.state.sysOf)
    if (!win) return null
    const box = boxOf(win, deskW, deskH)
    const w = size(220)
    return (
      <Popup
        x={Math.max(0, Math.min(box.x + 2 * edge + size(2), width - w))}
        y={deskTop + box.y + 2 * edge + size(26)}
        w={w}
        maxH={Math.max(size(48), height - deskTop - box.y - size(30))}
        body={[
          { label: 'Restore', onClick: () => restore(win.id), dim: !(win.max || win.snap), keys: 'Alt+F5' },
          { label: 'Hide', onClick: () => minimize(win.id), keys: 'Alt+F9' },
          { label: 'Maximize', onClick: () => (win.max ? frameos.setState('menu', null) : toggleMax(win.id)), dim: !!win.max, keys: 'Alt+F10' },
          null,
          ...(isSystem(win.id) ? [] : [{ label: 'Settings', onClick: () => sceneSettings(win.id) }]),
          { label: 'Window list', onClick: () => frameos.setState('menu', 'windows'), keys: 'Ctrl+Esc' },
          null,
          { label: 'Close', onClick: () => close(win.id), keys: 'Alt+F4' },
        ]}
      />
    )
  }
  // The desktop's pop-up menu, where it was pressed.
  const desktopMenu = () => {
    const at = app.state.popupAt || { x: 0, y: deskTop }
    const w = size(200)
    const any = wins.some((win) => !win.min)
    return (
      <Popup
        x={Math.max(0, Math.min(at.x, width - w))}
        y={Math.max(deskTop, Math.min(at.y, height - size(160)))}
        w={w}
        maxH={height - deskTop}
        body={[
          { label: 'Scenes - Icon View', icon: <FolderIcon s={16} />, onClick: sceneList },
          { label: 'Window list', icon: <WindowsGlyph />, onClick: () => frameos.setState('menu', 'windows'), keys: 'Ctrl+Esc' },
          null,
          { label: 'Tile', onClick: arrange('tile'), dim: !any },
          { label: 'Cascade', onClick: arrange('cascade'), dim: !any },
          { label: 'Show all', onClick: showAll, dim: !wins.some((win) => win.min) },
          null,
          { label: 'System Setup', icon: <SetupIcon s={16} />, onClick: controlPanel },
        ]}
      />
    )
  }
  const popupAt = (e) => {
    frameos.setState('popupAt', { x: Math.round(e.localX), y: Math.round(e.localY + deskTop) })
    frameos.setState('menu', 'popup')
  }
  // The LaunchPad's drawer over its Scenes button: the frame's scenes by category.
  const drawer = () => {
    if (!launch) return null
    const w = Math.min(width - size(6), size(230))
    const x = launch.x + edge + size(4) + size(60)
    return (
      <Popup
        x={Math.max(0, Math.min(x, width - w))}
        bottom={deskTop + launch.y}
        w={w}
        maxH={Math.max(size(48), launch.y - size(4))}
        body={sceneRows()}
      />
    )
  }
  const menuOpen = () => {
    if (menu === 'scenes') return scenesMenu()
    if (menu === 'windows') return windowList()
    if (full) return null
    if (menu === 'sys') return sysMenu()
    if (menu === 'popup') return desktopMenu()
    if (menu === 'drawer') return drawer()
    return null
  }
  const cover = menu ? <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', null)} onClick={() => {}} /> : null

  if (full) {
    // The panel is the window's. The pointer at the top edge brings the
    // WarpCenter; moved back over the window, it goes again, unless a menu is open.
    const peek = on(app.state.peek) || !!menu
    return (
      <div className={`relative w-full h-full bg-black text-black text-[${px(14)}]`}>
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 top-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        ) : menu ? null : (
          <div className={`absolute left-0 top-[${deskTop}px] w-full h-[${deskH}px]`} onPointerMove={() => frameos.setState('peek', false)} />
        )}
        {cover}
        {peek ? center('absolute left-0 top-0 w-full') : null}
        {menuOpen()}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  const hidden = hiddenUnder(shown, (w) => boxOf(w, deskW, deskH))
  return (
    <div className={`relative w-full h-full bg-[${DESK}] text-black text-[${px(14)}]`}>
      <div
        className={`absolute left-0 top-[${deskTop}px] w-[${deskW}px] h-[${deskH}px]`}
        {...point.desk}
        onPointerDown={(e) => (e.button === 1 ? popupAt(e) : point.desk.onPointerDown(e))}
        onLongPress={popupAt}
      >
        {icons()}
        <Band band={app.state.band} />
        {launchPad()}
        {shown.map(windowOf)}
        {outline()}
      </div>
      {cover}
      {center('absolute left-0 top-0 w-full')}
      {menuOpen()}
    </div>
  )
}

// F11 gives the panel to the window in front and takes it back; Escape closes a
// menu and leaves the full screen; Ctrl+Esc opens the Window List; Alt+Tab brings
// the window before forward (Shift: the one at the bottom), Alt+F4 closes the one
// in front, Alt+F9 hides it, Alt+F10 maximizes it and Alt+F5 restores it. The
// scene heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const payload = context.payload || {}
  const key = payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && payload.ctrl === true) {
    frameos.setState('menu', app.state.menu === 'windows' ? null : 'windows')
    return true
  }
  if (key === 'Escape' && (app.state.menu || on(app.state.full))) {
    frameos.setState('menu', null)
    frameos.setState('full', false)
    return true
  }
  const alt = payload.alt === true
  if (key === 'Tab' && alt) return actions(app).cycle(payload.shift === true)
  const id = app.frame.sceneId
  if (!alt || !id) return false
  if (key === 'F4') actions(app).close(id)
  else if (key === 'F9') actions(app).minimize(id)
  else if (key === 'F10') actions(app).toggleMax(id)
  else if (key === 'F5') actions(app).restore(id)
  else return false
  return true
}

// The windows wholly under a window above them (`wins` from the bottom up): their
// scenes are not drawn at all. A scene under something painted is a picture,
// and a picture on the desktop draws the whole desktop again for each frame of
// the window in front (1.9 fps for an animation on an ESP32, 2026-11-19).
function hiddenUnder(wins, boxIn) {
  const boxes = wins.map(boxIn)
  const hidden = new Set()
  wins.forEach((win, i) => {
    const b = boxes[i]
    for (let j = i + 1; j < wins.length; j++) {
      const a = boxes[j]
      if (a.x <= b.x && a.y <= b.y && a.x + a.w >= b.x + b.w && a.y + a.h >= b.y + b.h) {
        hidden.add(win.id)
        break
      }
    }
  })
  return hidden
}

// One scene at a time (windows off), the window around the frame's scene put
// away or closed (`keys`, in the state) stays so while the scene list or the
// settings show over it and when the focus only comes back to it
// (app.frame.wentBack), and shows again for a scene chosen, this one included,
// as a window does on the desktop. Where the frame keeps no layout from scene to
// scene (a preview, with no app.frame.scenes), the scene list opened from the
// desktop shows it again (`reopen`). Every desktop of windows has these same two.
function arrive(app, keys) {
  const current = app.frame.sceneId
  if (app.state.last === current) return
  frameos.setState('last', current)
  if (app.frame.systemScene === true || app.frame.wentBack === true) return
  for (const key of keys) if (app.state[key] === true) frameos.setState(key, false)
}
function reopen(app, keys) {
  if (Array.isArray(app.frame.scenes)) return
  for (const key of keys) if (app.state[key] === true) frameos.setState(key, false)
}

// Windows, or one scene at a time in the desktop's look (`windowMode`). Automatic
// is windows where the frame runs its scenes side by side without a limit (a Pi,
// the browser) or four at once, on a screen of 640x480 or more either way up,
// and one scene where it runs one or two (app.frame.windows: an ESP32 with 8 MB,
// where a window behind the one in front costs memory and frames, and a desktop
// of two is mostly the one in front) or the screen is smaller (a 480x480 panel
// has no room for a window beside another). An install from before, whose
// `windows` switch was turned off, stays off.
const windowsOn = (app) => {
  const mode = app.state.windowMode
  if (mode === 'on') return true
  if (mode === 'off' || app.state.windows === false || app.state.windows === 'false') return false
  const most = app.frame.windows
  const long = Math.max(app.frame.width || 0, app.frame.height || 0)
  const short = Math.min(app.frame.width || 0, app.frame.height || 0)
  return !(most > 0 && most <= 2) && long >= 640 && short >= 480
}

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  const now = new Date()
  dress(app, THEMES, 'warp')
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const settingsOpen = builtIn && name.includes('settings')
  const frameOpen = settingsOpen && name.startsWith('Frame')
  const listOpen = builtIn && !settingsOpen
  const title = listOpen
    ? 'Scenes - Icon View'
    : frameOpen
      ? 'System Setup'
      : settingsOpen
        ? `${app.state.openedOver || 'Scene'} - Settings`
        : name
  // Hidden, the window's button in the WarpCenter brings it back; closed, it has
  // none, and the Desktop menu opens a scene again (arrive).
  const KEYS = ['hidden', 'closed']
  arrive(app, KEYS)
  const closed = app.state.closed === true
  const hidden = !builtIn && (closed || app.state.hidden === true)
  const toggleHide = () => frameos.setState('hidden', !hidden)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(settingsOpen ? 'sceneSettings' : 'sceneSwitcher')
  // The window a built-in scene opened over: its button stays in the WarpCenter.
  const openWindow = closed ? null : builtIn ? app.state.openedOver : name
  const taskW = Math.round(Math.min(size(180), width * 0.34))
  const icon = listOpen ? <FolderIcon s={16} /> : builtIn ? <SetupIcon s={16} /> : <WindowIcon />
  return (
    <div className={`flex flex-col w-full h-full bg-[${DESK}] text-black text-[${px(14)}]`}>
      <Center>
        <Toggle pressed={listOpen} className={`shrink-0 w-[${size(44)}px]`} onClick={() => (reopen(app, KEYS), frameos.dispatch('sceneSwitcher', { swap: true }))}>
          <DesktopGlyph />
          <Caret />
        </Toggle>
        {openWindow ? (
          <Toggle pressed={!builtIn && !hidden} className={`w-[${taskW}px] min-w-0`} onClick={builtIn ? () => (frameos.setState('hidden', false), closeBuiltIn()) : toggleHide}>
            <WindowIcon />
            <span className="flex-1 min-w-0 truncate">{openWindow}</span>
          </Toggle>
        ) : null}
        <Toggle pressed={settingsOpen && !frameOpen} className="shrink-0" onClick={() => frameos.dispatch('sceneSettings')}>
          <GearGlyph />
        </Toggle>
        <div className="flex-1" />
        <Monitor app={app} now={now} wide={width >= size(560)} onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })} />
      </Center>
      {hidden ? (
        <div className="flex-1" />
      ) : app.state.showWindow !== false && app.state.showWindow !== 'false' ? (
        <Frame className="flex-1 min-h-0">
          <TitleBar
            title={title}
            icon={icon}
            onSettings={builtIn ? undefined : () => frameos.dispatch('sceneSettings')}
            onHide={builtIn ? closeBuiltIn : toggleHide}
            onClose={builtIn ? closeBuiltIn : () => frameos.setState('closed', true)}
          />
          <div className="flex flex-col flex-1 min-h-0">
            <yield />
          </div>
        </Frame>
      ) : (
        <yield />
      )}
    </div>
  )
}
